gceSTATUS
gckIOMMU_Construct(IN gckOS Os, OUT gckIOMMU *Iommu)
{
    printk(KERN_INFO "FUNC_ENTRY: Entering function gckIOMMU_Construct at %s:%d\n", __FILE__, __LINE__);
    gceSTATUS            status = gcvSTATUS_OK;
    gckIOMMU             iommu  = gcvNULL;
    struct device       *dev;
    dma_addr_t           dmaHandle;
    gctUINT64            phys;
    struct iommu_domain *domain;
    gctUINT32            gfp = GFP_KERNEL;

    gcmkHEADER_ARG("Os=%p", Os);

    dev    = &Os->device->platform->device->dev;
#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 2, 0)
    domain = iommu_get_domain_for_dev(dev);
#else
    domain = gcvNULL;
#endif

    printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_map_page from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_map_page called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_map_page\n");
    if (domain) {
        struct page *page;

        page = alloc_page(gfp);
        if (!page)
            gcmkONERROR(gcvSTATUS_OUT_OF_MEMORY);

        phys = page_to_phys(page);

        dmaHandle = dma_map_page(dev, page, 0, PAGE_SIZE, DMA_TO_DEVICE);

        printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_unmap_page from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_unmap_page called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_unmap_page\n");
        if (dmaHandle)
            dma_unmap_page(dev, dmaHandle, PAGE_SIZE, DMA_FROM_DEVICE);

        __free_page(page);

        /* Iommu bypass */
        if (phys == dmaHandle) {
            *Iommu = gcvNULL;

            gcmkFOOTER();
            return status;
        }
    } else {
        /* Don't enable iommu */
        *Iommu = gcvNULL;

        gcmkFOOTER();
        return status;
    }

    gcmkONERROR(gckOS_Allocate(Os, gcmSIZEOF(gcsIOMMU), (gctPOINTER *)&iommu));

    gckOS_ZeroMemory(iommu, gcmSIZEOF(gcsIOMMU));

    printk(KERN_INFO "DMA_INSTRUMENT: About to call dma_map_page from function %s at %s:%d\n", __func__, __FILE__, __LINE__);
printk(KERN_INFO "DMA_STACK_START: Stack trace for dma_map_page called from %s\n", __func__);
dump_stack();
printk(KERN_INFO "DMA_STACK_END: End of stack trace for dma_map_page\n");
    if (Os->paddingPage) {
        iommu->paddingPageDmaHandle =
            dma_map_page(dev, Os->paddingPage, 0, PAGE_SIZE, DMA_TO_DEVICE);
    }

    iommu->domain = domain;
    iommu->device = dev;

    *Iommu = iommu;

    gcmkPRINT("[galcore]: Enable IOMMU\n");
OnError:
    if (gcmIS_ERROR(status))
        gckIOMMU_Destory(Os, iommu);

    gcmkFOOTER();
    return status;
}

