                                           mdlPriv->nonContiguousPages,
                                           NumPages,
                                           0,
                                           NumPages << PAGE_SHIFT,
                                           normal_gfp);

#else
        result = alloc_sg_list_from_pages(&mdlPriv->sgt.sgl,
                                          mdlPriv->nonContiguousPages,
                                          NumPages,
                                          0,
